begin;

insert into public.bko_clients(slug,name,original_name,website_url,website_original,website_verified,logo_local_path,logo_storage_path,logo_verified,logo_authorized,logo_source,logo_source_original,logo_status_original,verification_status,observations,sector,sector_source,description,sort_order,active,published,featured,relation_authorized,authorization_reference,logo_authorization_reference,original_row,logo_width,logo_height,logo_background) values('funeraria-reino-del-senor','Funeraria Reino del Señor','Funeraria Reino del Señor','','',false,'assets/clientes/funeraria-reino-del-senor.png','',true,true,'Logotipo entregado por el responsable del sitio (clientes/funeraria reino del señor.png)','clientes/funeraria reino del señor.png','Logotipo entregado por el cliente','verified','Cliente agregado por instrucción del responsable del sitio (26-11-2026). Teléfono de contacto: +56 9 9920 3562.','general','','Servicios funerarios. Teléfono de contacto: +56 9 9920 3562.',380,true,true,true,true,'Instrucción del responsable del sitio, 26-11-2026: agregar Funeraria Reino del Señor al carrusel con su teléfono de contacto.','Instrucción del responsable del sitio, 26-11-2026, de mostrar el logotipo de Funeraria Reino del Señor.','clientes/funeraria reino del señor.png, nuevo cliente con su logo y teléfono +56 9 9920 3562',366,348,'white') on conflict(slug) do nothing;

